1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.Map;
7	import java.util.Set;
8	import java.util.regex.Pattern;
9	
10	import net.officefloor.plugin.variable.Out;
11	import org.springframework.samples.petclinic.mapper.Localities;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
14	import org.springframework.web.bind.annotation.RequestBody;
15	
16	/**
17	 * Rejects a create request that is missing or blank in any required owner field, so an
18	 * incomplete body is a 400 whose {@code errors} array names each offending field. Also
19	 * normalizes the telephone to E.164 form (see {@link TelephoneE164}), republishing the
20	 * normalized value so it is stored and returned as {@code telephone}; a telephone that
21	 * cannot form a valid E.164 number is a 400 too.
22	 * The optional {@code email} is validated only when present: a syntactically invalid
23	 * address is a 400, an otherwise-valid address whose domain is on the disposable-domain
24	 * blocklist is a 400, otherwise it is normalized to lower-case and republished so it is
25	 * stored and returned lower-cased.
26	 * The address may be supplied in a structured form ({@code addressLine1} plus an optional
27	 * {@code addressLine2}) or as the flat {@code address}; the structured form is preferred when a
28	 * non-blank {@code addressLine1} is present. Whichever fields are supplied are normalized (see
29	 * {@link AddressNormalizer}) and republished, and the stored/returned {@code address} is the
30	 * composed value (normalized {@code addressLine1}, plus a space and the normalized
31	 * {@code addressLine2} when present) falling back to the normalized flat {@code address}. An owner
32	 * that supplies an address in neither form is a required-field 400.
33	 * The optional {@code registrationDate} is validated only when present: a date later than
34	 * the server's current date is a 400.
35	 * Runs first and republishes the body as a variable for {@link BuildOwner}.
36	 */
37	public class ValidateOwnerFields {
38	
39	    /** Syntactic email check: one '@', non-empty local part, and a dotted domain. */
40	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
41	
42	    /** Disposable email domains that are rejected: a syntactically valid address whose domain
43	     *  (lower-cased) is listed here is a 400. */
44	    private static final Set<String> DISPOSABLE_DOMAINS =
45	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
46	
47	    /** A well-formed postcode is exactly four digits. */
48	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
49	
50	    /** Region -> inclusive 4-digit postcode range {low, high}. A city whose region is not
51	     *  listed (derives "UNKNOWN") accepts any well-formed 4-digit postcode. */
52	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
53	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
54	
55	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
56	            throws MissingFieldsException {
57	        List<String> errors = new ArrayList<>();
58	        if (isBlank(request.getFirstName())) {
59	            errors.add("firstName");
60	        }
61	        if (isBlank(request.getLastName())) {
62	            errors.add("lastName");
63	        }
64	        applyAddress(request, errors);
65	        if (isBlank(request.getCity())) {
66	            errors.add("city");
67	        }
68	        String telephone = TelephoneE164.normalize(request.getTelephone());
69	        if (telephone == null) {
70	            errors.add("telephone");
71	        }
72	        else {
73	            request.setTelephone(telephone);
74	        }
75	        String email = request.getEmail();
76	        if (email != null && !email.isBlank()) {
77	            String normalized = email.trim().toLowerCase();
78	            if (!EMAIL.matcher(normalized).matches()) {
79	                errors.add("email");
80	            }
81	            else if (DISPOSABLE_DOMAINS.contains(normalized.substring(normalized.indexOf('@') + 1))) {
82	                errors.add("email");
83	            }
84	            else {
85	                request.setEmail(normalized);
86	            }
87	        }
88	        // Postcode is optional; validated only when present. A malformed (non-4-digit) postcode
89	        // is a 400, and a well-formed postcode outside its city's region range is a 400 too.
90	        // A city with no known region accepts any 4-digit postcode.
91	        String postcode = request.getPostcode();
92	        if (postcode != null && !postcode.isBlank()) {
93	            String trimmed = postcode.trim();
94	            if (!POSTCODE.matcher(trimmed).matches() || !inRegionRange(request.getCity(), trimmed)) {
95	                errors.add("postcode");
96	            }
97	            else {
98	                request.setPostcode(trimmed);
99	            }
100	        }
101	        // registrationDate is optional; validated only when present. A date later than the
102	        // server's current date is a 400 — an owner cannot be registered in the future.
103	        LocalDate registrationDate = request.getRegistrationDate();
104	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
105	            errors.add("registrationDate");
106	        }
107	        if (!errors.isEmpty()) {
108	            throw new MissingFieldsException(errors);
109	        }
110	        validated.set(request);
111	    }
112	
113	    /**
114	     * Normalizes whichever address fields are supplied and republishes them, preferring the
115	     * structured form. A non-blank {@code addressLine1} (with an optional {@code addressLine2})
116	     * wins over the flat {@code address}; either form satisfies the address requirement. The
117	     * stored/returned {@code address} is the composed value: the normalized {@code addressLine1},
118	     * plus a single space and the normalized {@code addressLine2} when present, falling back to the
119	     * normalized flat {@code address}. An owner supplying neither is a required-field 400.
120	     */
121	    private static void applyAddress(OwnerFieldsDto request, List<String> errors) {
122	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
123	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
124	        String flat = AddressNormalizer.normalize(request.getAddress());
125	        if (!line1.isEmpty()) {
126	            request.setAddressLine1(line1);
127	            String composed = line1;
128	            if (!line2.isEmpty()) {
129	                request.setAddressLine2(line2);
130	                composed = line1 + " " + line2;
131	            }
132	            else {
133	                request.setAddressLine2(null);
134	            }
135	            request.setAddress(composed);
136	        }
137	        else if (!flat.isEmpty()) {
138	            request.setAddress(flat);
139	        }
140	        else {
141	            errors.add("address");
142	        }
143	    }
144	
145	    private static boolean isBlank(String value) {
146	        return value == null || value.isBlank();
147	    }
148	
